std::vector<int> data;
const size_t COUNT = 5000;

// Best Practice 1: Use reserve() to preallocate memory
// Prevents costly internal reallocations/copies during additions
data.reserve(COUNT);

for (size_t i = 0; i < COUNT; ++i) {
    // Best Practice 2: Use push_back or emplace_back
    // emplace_back avoids temporary object creation/copy if complex type
    data.push_back(i);
}

// Alternative for range insertion (already reserved)
std::vector<int> temp = {10, 20};
data.insert(data.end(), temp.begin(), temp.end());
data.shrink_to_fit(); // Optional: reclaim excess capacity
data.clear();
data.capacity(); // Current allocated size
data.size();     // Current element count
